{
  "sop_id": "SOP-013",
  "title": "Bill of Quantities (BOQ) Review",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create and assign ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check BOQ completeness",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Verify quantities against drawings and rates against schedule",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Summarize variance, list non-standard items, and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Dependency: Drawings revision or take-off confirmation",
      "role": "External",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval/rejection",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit after rejection",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "after 2 rejections or for exceptions (EX-HIGHVAL, EX-NEWITEM)"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Operations",
      "item": "Drawings revision or take-off confirmation",
      "parallel_group": null
    }
  ],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.90
}
